## 🔮 The Cyber-Vibe Quiz: What's Your True Genre Persona?

Answer 3 quick questions to calculate your Netflix Vibe Index and unlock your custom movie match:

```{=html}
&lt;div style="background: linear-gradient(135deg, #222B2E 0%, #1A2224 100%); border: 1px solid #3F4E4F; border-radius: 18px; padding: 26px; margin: 25px 0; box-shadow: 0 0 30px rgba(63, 78, 79, 0.25);"&gt;

  &lt;!-- Question 1 --&gt;
  &lt;div style="margin-bottom: 20px;"&gt;
    &lt;div style="color: #F4F0E5; font-weight: 700; font-size: 1.05rem; margin-bottom: 10px;"&gt;1. Ideal Friday Night Scenario:&lt;/div&gt;
    &lt;div style="display: flex; gap: 12px; flex-wrap: wrap;"&gt;
      &lt;button class="quiz-btn q1" data-type="action" onclick="answerQuiz(1, 'action', this)" style="background: #1A2224; border: 1px solid #BD7B46; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;💥 High-speed chase through dimly lit city streets&lt;/button&gt;
      &lt;button class="quiz-btn q1" data-type="romance" onclick="answerQuiz(1, 'romance', this)" style="background: #1A2224; border: 1px solid #6BA3A7; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;🌧️ Cozy vintage café conversation in the pouring rain&lt;/button&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;!-- Question 2 --&gt;
  &lt;div style="margin-bottom: 20px;"&gt;
    &lt;div style="color: #F4F0E5; font-weight: 700; font-size: 1.05rem; margin-bottom: 10px;"&gt;2. Your Favorite Plot Twist:&lt;/div&gt;
    &lt;div style="display: flex; gap: 12px; flex-wrap: wrap;"&gt;
      &lt;button class="quiz-btn q2" data-type="action" onclick="answerQuiz(2, 'action', this)" style="background: #1A2224; border: 1px solid #BD7B46; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;🕶️ The mentor was actually the villainous mastermind&lt;/button&gt;
      &lt;button class="quiz-btn q2" data-type="romance" onclick="answerQuiz(2, 'romance', this)" style="background: #1A2224; border: 1px solid #6BA3A7; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;💌 They secretly kept each other's letters for 10 years&lt;/button&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;!-- Question 3 --&gt;
  &lt;div style="margin-bottom: 20px;"&gt;
    &lt;div style="color: #F4F0E5; font-weight: 700; font-size: 1.05rem; margin-bottom: 10px;"&gt;3. The Protagonist's Signature Prop:&lt;/div&gt;
    &lt;div style="display: flex; gap: 12px; flex-wrap: wrap;"&gt;
      &lt;button class="quiz-btn q3" data-type="action" onclick="answerQuiz(3, 'action', this)" style="background: #1A2224; border: 1px solid #BD7B46; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;⚔️ Tactical compass & grappling hook&lt;/button&gt;
      &lt;button class="quiz-btn q3" data-type="romance" onclick="answerQuiz(3, 'romance', this)" style="background: #1A2224; border: 1px solid #6BA3A7; color: #F4F0E5; padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; transition: all 0.2s;"&gt;🧣 A borrowed wool coat that carries old memories&lt;/button&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;!-- Quiz Result Box --&gt;
  &lt;div id="quiz-result" style="display: none; background: #1A2224; border-radius: 12px; padding: 22px; border: 1px solid #3F4E4F; text-align: center; margin-top: 20px;"&gt;
    &lt;div style="font-size: 0.9rem; color: #A27B5C; font-weight: 800; letter-spacing: 2px; text-transform: uppercase;"&gt;YOUR PERSONALITY MATRIX:&lt;/div&gt;
    &lt;h3 id="quiz-title" style="font-family: 'Playfair Display', Georgia, serif; color: #F4F0E5; font-size: 1.6rem; margin: 8px 0; text-shadow: 0 0 15px #BD7B46;"&gt;CALCULATING...&lt;/h3&gt;
    &lt;p id="quiz-desc" style="color: #E4DED3; font-size: 1rem; max-width: 550px; margin: 0 auto 15px auto;"&gt;&lt;/p&gt;
    &lt;div style="height: 12px; border-radius: 8px; background: #6BA3A7; max-width: 450px; margin: 0 auto 15px auto; overflow: hidden; display: flex;"&gt;
      &lt;div id="quiz-meter" style="width: 50%; background: #BD7B46; transition: width 0.6s ease;"&gt;&lt;/div&gt;
    &lt;/div&gt;
    &lt;div id="quiz-breakdown" style="color: #A27B5C; font-size: 0.9rem; font-weight: bold;"&gt;&lt;/div&gt;
  &lt;/div&gt;

&lt;/div&gt;

&lt;script&gt;
const quizAnswers = { 1: null, 2: null, 3: null };

function answerQuiz(q, choice, btn) {
  quizAnswers[q] = choice;

  // Update button active state
  document.querySelectorAll('.q' + q).forEach(b =&gt; {
    b.style.opacity = '0.5';
    b.style.boxShadow = 'none';
  });
  btn.style.opacity = '1';
  btn.style.boxShadow = choice === 'action' ? '0 0 15px rgba(189,123,70,0.5)' : '0 0 15px rgba(107,163,167,0.5)';

  // If all answered, calculate
  if (quizAnswers[1] && quizAnswers[2] && quizAnswers[3]) {
    let actionCount = Object.values(quizAnswers).filter(v =&gt; v === 'action').length;
    let actionPct = Math.round((actionCount / 3) * 100);
    let romancePct = 100 - actionPct;

    const resBox = document.getElementById('quiz-result');
    const qTitle = document.getElementById('quiz-title');
    const qDesc = document.getElementById('quiz-desc');
    const qMeter = document.getElementById('quiz-meter');
    const qBreakdown = document.getElementById('quiz-breakdown');

    qMeter.style.width = actionPct + '%';
    qBreakdown.innerHTML = `&lt;span style="color:#BD7B46;"&gt;${actionPct}% Action Adrenaline&lt;/span&gt; | &lt;span style="color:#6BA3A7;"&gt;${romancePct}% Romantic Soul&lt;/span&gt;`;

    if (actionCount === 3) {
      qTitle.textContent = "⚡ PURE ADRENALINE JUNKIE";
      qTitle.style.textShadow = "0 0 20px #BD7B46";
      qDesc.textContent = "You need high stakes, tight timing, and non-stop momentum. Netflix's 453 action titles are tailored to your pace!";
    } else if (actionCount === 2) {
      qTitle.textContent = "💥 KINETIC ROMANTIC (70/30)";
      qTitle.style.textShadow = "0 0 20px #BD7B46";
      qDesc.textContent = "You crave pulse-pounding stakes, but with deep emotional connection and chemistry at the heart of the story.";
    } else if (actionCount === 1) {
      qTitle.textContent = "💖 HOPEFUL ADVENTURER (30/70)";
      qTitle.style.textShadow = "0 0 20px #A27B5C";
      qDesc.textContent = "You believe in heartfelt declarations and poetic sparks, but love a little thrilling escapism on the side!";
    } else {
      qTitle.textContent = "✨ 100% UNAPOLOGETIC ROMANTIC";
      qTitle.style.textShadow = "0 0 20px #6BA3A7";
      qDesc.textContent = "Give you soft lighting, passionate dialogues, and winter warmth. Netflix's surging romance catalog is your personal sanctuary.";
    }

    resBox.style.display = 'block';
    resBox.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}
&lt;/script&gt;
